from PyQt6.QtWidgets import QWidget,QVBoxLayout,QFormLayout,QComboBox,QSlider,QCheckBox,QLineEdit
from PyQt6.QtCore import Qt
class AlarmSettings(QWidget):
    def __init__(self,c,save):
        super().__init__(); self.c=c; self.save=save; l=QVBoxLayout(self); f=QFormLayout(); self.target=QComboBox(); self.target.addItems(['laptop','phone','both']); self.target.setCurrentText(c['alarm']['device_target']); self.preset=QComboBox(); self.preset.addItems(['defcon1','tactical','stealth','custom']); self.preset.setCurrentText(c['alarm']['active_preset']); self.volume=QSlider(Qt.Orientation.Horizontal); self.volume.setRange(0,100); self.volume.setValue(c['alarm']['volume']); self.tts=QCheckBox('Enable text-to-speech'); self.tts.setChecked(c['alarm']['tts_enabled']); self.flash=QCheckBox('Enable screen flash'); self.flash.setChecked(c['alarm']['screen_flash']); self.message=QLineEdit(c['alarm']['custom_tts']); f.addRow('Device target',self.target);f.addRow('Preset',self.preset);f.addRow('Volume',self.volume);f.addRow(self.tts);f.addRow(self.flash);f.addRow('Custom TTS',self.message);l.addLayout(f); [w.connect(self.commit) for w in (self.target.currentTextChanged,self.preset.currentTextChanged,self.volume.valueChanged,self.tts.toggled,self.flash.toggled,self.message.editingFinished)];l.addStretch()
    def commit(self): self.save('alarm',{'device_target':self.target.currentText(),'active_preset':self.preset.currentText(),'volume':self.volume.value(),'tts_enabled':self.tts.isChecked(),'screen_flash':self.flash.isChecked(),'custom_tts':self.message.text()})
